div.div:
Zone- idZone : BigInt {PK}
- nom : String
- typeZone : String {compound_ferme, quartier_ouvert}

Vehicule- idVehicule : BigInt {PK}
- immatriculation : String
- typeVehicule : String {citadine, berline, suv_4x4, utilitaire}

Abonnement- idAbonnement : BigInt {PK}
- frequence : String {hebdomadaire, bimensuelle, mensuelle}
- dateDebut : Date
- dateFin : Date

Reservation- idReservation : BigInt {PK}
- dateReservation : Date
- creneau : String {matin=4h-6h30, soir=20h-00h} (RG3)
- statut : StatutReservation «enum»+ choisirCreneau()
+ annuler() {RG4 : jusqu'à la veille}

Agent- idAgent : BigInt {PK}
- role : Role «enum»
- nom : String
- telephone : String+ consulterPlanning()
+ demarrerMission()
+ terminerMission()
+ signalerAnomalie()
+ creerTournee() {role=chef_equipe}
+ affecterAgent() {role=chef_equipe}
+ controlerQualite() {role=chef_equipe}
+ suivreRevenus() {role=chef_equipe}

Mission- idMission : BigInt {PK}
- demarreeLe : TimestampTZ (null tant que non démarrée)
- termineeLe : TimestampTZ (null tant que non terminée)
- photoAvant : String (RG2, obligatoire)
- photoApres : String (RG2, obligatoire)+ demarrer()
+ terminer() {precondition: demarreeLe ≠ null}

Avis- idAvis : BigInt {PK}
- note : Integer {1..5}
- commentaire : String+ deposer() {precondition: mission.termineeLe ≠ null}

Signalement- idSignalement : BigInt {PK}
- typeSignalement : String {client, agent}
- description : String+ signaler()
